export function languageCode(state){return state?.app_state?.languageCode==='lv'?'lv':'en';}
export function localeFor(lang){return lang==='lv'?'lv-LV':'en-GB';}
export function t(raw,lang='en'){
  raw=String(raw??'');if(lang!=='lv'||!raw)return raw;
  // Declare before all dynamic translation patterns. Accessing this binding
  // before the declaration crashed startup for Latvian users in v1.7.9.
  let m;
  if(LV[raw]!=null)return LV[raw];
  if((m=/^Duration (\d{1,2}:\d{2}(?::\d{2})?)$/.exec(raw)))return `Ilgums ${m[1]}`;
  if((m=/^Strength: (.+) · Cardio: (.+)$/.exec(raw)))return `Spēks: ${t(m[1],lang)} · Kardio: ${t(m[2],lang)}`;
  if((m=/^Target (.+) · finish whenever you are done$/.exec(raw)))return `Mērķis ${m[1]} · pabeidz, kad esi gatavs`;
  if((m=/^RPE (\d+(?:\.\d+)?)$/.exec(raw)))return `RPE ${m[1]}`;
  if((m=/^(.+) · cardio RPE (\d+(?:\.\d+)?)$/.exec(raw)))return `${t(m[1],lang)} · kardio RPE ${m[2]}`;
  if((m=/^Cardio time (.+)$/.exec(raw)))return `Kardio ilgums ${m[1]}`;

  if((m=/^(\d+) exercises?$/.exec(raw)))return `${m[1]} ${Number(m[1])===1?'vingrinājums':'vingrinājumi'}`;
  if((m=/^(\d+) days?$/.exec(raw)))return `${m[1]} ${Number(m[1])===1?'diena':'dienas'}`;
  if((m=/^(\d+) weeks?$/.exec(raw)))return `${m[1]} ${Number(m[1])===1?'nedēļa':'nedēļas'}`;
  if((m=/^(\d+) months?$/.exec(raw)))return `${m[1]} ${Number(m[1])===1?'mēnesis':'mēneši'}`;
  if((m=/^(\d+(?:\.\d+)?) years?$/.exec(raw)))return `${m[1]} gadi`;
  if((m=/^(\d+) reps$/.exec(raw)))return `${m[1]} atkārtojumi`;
  if((m=/^(?:SET )?(\d+)\/(\d+) SKIPPED$/.exec(raw)))return `${m[1]}/${m[2]} IZLAISTS`;
  if((m=/^SET (\d+) \/ (\d+)$/.exec(raw)))return `${m[1]}/${m[2]}`;
  if((m=/^Suggested set (\d+)$/.exec(raw)))return `Ieteiktais ${m[1]}. piegājiens`;
  if((m=/^Suggested increase: (.+)$/.exec(raw)))return `Ieteiktais palielinājums: ${m[1]}`;
  if((m=/^Volume (.+)$/.exec(raw)))return `Apjoms ${m[1]}`;
  if((m=/^(.+) progress$/.exec(raw)))return `${t(m[1],lang)} progress`;
  if((m=/^Start (.+)\?$/.exec(raw)))return `Sākt ${m[1]}?`;
  if((m=/^Delete (.+)\?$/.exec(raw)))return `Dzēst ${m[1]}?`;
  if((m=/^(.+) will be removed from Tracker\. Existing backup data is not otherwise changed\.$/.exec(raw)))return `${m[1]} tiks noņemts no Tracker. Esošie rezerves kopiju dati netiks mainīti.`;
  if((m=/^Skip (.+)\?$/.exec(raw)))return `Izlaist ${m[1]}?`;
  if((m=/^(.+) SKIPPED · NEXT: (.+)$/.exec(raw)))return `${m[1]} IZLAISTS · TĀLĀK: ${m[2]}`;
  if((m=/^(.+) SKIPPED$/.exec(raw)))return `${m[1]} IZLAISTS`;
  if((m=/^It’s been (\d+) (day|days) since your last recorded workout\.$/.exec(raw)))return `Kopš pēdējā saglabātā treniņa pagājušas ${m[1]} ${Number(m[1])===1?'diena':'dienas'}.`;
  if((m=/^(.+) · in progress$/.exec(raw)))return `${m[1]} · notiek`;
  if((m=/^(.+) · next(?: · (.+))?$/.exec(raw)))return `${m[1]} · nākamais${m[2]?` · ${m[2]}`:''}`;
  if((m=/^NEXT · (.+)$/.exec(raw)))return `TĀLĀK · ${m[1]}`;
  if((m=/^RIR · target (.+)$/.exec(raw)))return `RIR · mērķis ${m[1]}`;
  return raw;
}

