export function message(key, lang='en', parameters={}) {
  const value=MESSAGES[key];
  const template=value ? value[lang==='lv'?1:0] : t(key,lang);
  return String(template).replace(/\{([a-zA-Z][a-zA-Z0-9_]*)\}/g,(token,name)=>Object.prototype.hasOwnProperty.call(parameters,name)?String(parameters[name]??''):token);
}
export function hasMessage(key) { return Object.prototype.hasOwnProperty.call(MESSAGES,key) || Object.prototype.hasOwnProperty.call(LV,key); }
export const interfaceText = message;

const EXCLUDED='[data-user-content],[translate="no"],.notranslate,script,style,code,pre,textarea,input';
const legacyTextSources=new WeakMap();
const legacyAttributeSources=new WeakMap();

function elements(root,selector) {
  if(!root?.querySelectorAll)return[];
  const found=[...root.querySelectorAll(selector)];
  if(root.matches?.(selector))found.unshift(root);
  return found;
}
function excluded(node) { return Boolean(node?.parentElement?.closest(EXCLUDED) || node?.closest?.(EXCLUDED)); }
function paramsFor(el) {
  try {const value=JSON.parse(el.dataset.i18nParams || '{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return{};}
}
function translateMarkedText(el, lang) {
  if(excluded(el))return;
  // A keyed container must not flatten child controls or user content.
  if(el.children.length)return;
  const translated=message(el.dataset.i18n || el.dataset.i18nKey,lang,paramsFor(el));
  if(el.textContent!==translated)el.textContent=translated;
}
function translateLegacyLeaf(el, lang) {
  if(excluded(el))return;
  for(const node of [...el.childNodes]) {
    if(node.nodeType!==3 || excluded(node))continue;
    const value=node.nodeValue || '',trim=value.trim();if(!trim)continue;
    let source=legacyTextSources.get(node);
    if(!source || (value!==source.last && value!==source.raw)){source={raw:value,last:value};legacyTextSources.set(node,source);}
    const raw=source.raw.trim();
    // These captions and controls are authored UI. Dynamic user names never enter this pass.
    const translated=t(raw,lang); const next=source.raw.replace(raw,translated);
    if(node.nodeValue!==next)node.nodeValue=next;
    source.last=next;
  }
}

/** Translate only declared UI keys and a narrow compatibility set of static controls.
 * No TreeWalker over arbitrary app text. User names, notes, account names,
 * exercise options and history are never inferred to be interface strings.
 * New templates should use data-i18n / data-i18n-{aria-label,title,placeholder}.
 */
export function localizeDom(root,lang='en',{legacy=true}={}) {
  if(!root)return;
  const language=lang==='lv'?'lv':'en';
  if(root.ownerDocument)root.ownerDocument.documentElement.lang=language;
  elements(root,'[data-i18n],[data-i18n-key]').forEach(el=>translateMarkedText(el,language));
  for(const attr of ['aria-label','title','placeholder']) {
    elements(root,`[data-i18n-${attr}]`).forEach(el=>{
      if(excluded(el) && !el.matches('input,textarea'))return;
      if(el.closest('[data-user-content],[translate="no"],.notranslate'))return;
      el.setAttribute(attr,message(el.getAttribute(`data-i18n-${attr}`),language,paramsFor(el)));
    });
  }
  if(!legacy)return;
  const staticSelectors=[
    '.field','.field-label','.section-title','.metric-label',
    '.nav button>span:last-child','.dialog-actions button','.rir-row button','.rir-heading',
    '.progress-metrics button','.reorder-hint>span:last-child',
    '.view>h1','.friends-head h1','.workout-complete-title',
    '#starter-goal option','#starter-experience option',
    '[data-interface-text]','[data-interface-options] option',
  ];
  elements(root,staticSelectors.join(',')).forEach(el=>{if(!el.hasAttribute('data-i18n')&&!el.hasAttribute('data-i18n-key'))translateLegacyLeaf(el,language);});
  // Native option sets below are finite UI enums. Exercise/name choices are excluded.
  const enumSelectIds=['f-type','f-equipment','f-ramp','f-db-load','f-dumbbells','f-tracking','f-tracking-mode','tr-unit'];
  elements(root,'select').forEach(select=>{
    if(enumSelectIds.includes(select.id) || select.getAttribute('aria-label')==='Period' || select.dataset.interfaceOptions!=null) {
      select.dataset.interfaceOptions='';[...select.options].forEach(option=>translateLegacyLeaf(option,language));
    }
  });
  // Accessible names on known UI controls are safe exact strings; never translate values.
  elements(root,'.icon-btn[aria-label],.tracker-step-btn[aria-label],.superset-link-btn[aria-label],select[aria-label],input[placeholder],textarea[placeholder]').forEach(el=>{
    if(el.closest('[data-user-content],[translate="no"],.notranslate'))return;
    const saved=legacyAttributeSources.get(el)||{};
    for(const attr of ['aria-label','placeholder']) {
      if(el.hasAttribute(`data-i18n-${attr}`))continue;
      const value=el.getAttribute(attr);if(!value)continue;
      saved[attr] ||= value;el.setAttribute(attr,t(saved[attr],language));
    }
    legacyAttributeSources.set(el,saved);
  });
}

